from fractions import Fraction

def compute_S_parts(M):
    S1 = 0
    prod1 = 1
    for n in range(1, M):
        prod1 *= (M + n)
        S1 += Fraction(M**n, prod1)

    S2 = 0
    prod2 = 1
    for n in range(1, M):
        prod2 *= Fraction(M - n, M)
        S2 += prod2

    return float(S1), float(S2)

for M in [10, 100, 1000]:
    s1, s2 = compute_S_parts(M)
    print(f"M={M}, S1={s1}, S2={s2}, S1-S2={s1-s2}")
